/**
 * Pure OCR storage path rules. Shared by export, sync, purge and their tests.
 *
 * Storage paths are generated by the app as:
 *   <contributor uuid>/<page uuid>/<line number>.<webp|jpg>
 * Nothing in a path is trusted: the path must match this shape, the page id and
 * line number must match the database row, and the extension decides the local
 * file name. Remote names are never used as local paths.
 */

export type OcrImageExtension = "webp" | "jpg";

export type OcrStoragePath = {
  userId: string;
  pageId: string;
  idx: number;
  ext: OcrImageExtension;
};

const UUID =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const STORAGE_PATH =
  /^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\/([1-9]|[1-3][0-9]|40)\.(webp|jpg)$/i;

export function isUuid(value: unknown): value is string {
  return typeof value === "string" && UUID.test(value);
}

export function isOcrImageExtension(
  value: unknown,
): value is OcrImageExtension {
  return value === "webp" || value === "jpg";
}

/**
 * Returns the normalized path parts, or null when the path does not exactly
 * match the expected page and line. `expectedPageId` and `expectedIdx` come
 * from the database row, never from the path.
 */
export function parseOcrStoragePath(
  storagePath: unknown,
  expectedPageId: string,
  expectedIdx: number,
): OcrStoragePath | null {
  if (typeof storagePath !== "string" || !isUuid(expectedPageId)) return null;
  if (!Number.isInteger(expectedIdx) || expectedIdx < 1 || expectedIdx > 40) {
    return null;
  }

  const match = STORAGE_PATH.exec(storagePath);
  if (!match) return null;

  const pageId = match[2].toLowerCase();
  const idx = Number(match[3]);
  const ext = match[4].toLowerCase();

  if (pageId !== expectedPageId.toLowerCase() || idx !== expectedIdx) {
    return null;
  }
  if (!isOcrImageExtension(ext)) return null;

  return {
    userId: match[1].toLowerCase(),
    pageId,
    idx,
    ext,
  };
}

export function pad2(value: number): string {
  return String(value).padStart(2, "0");
}

/** Stable across exports: page id plus the original line number. */
export function stableOcrId(pageId: string, idx: number): string {
  if (!isUuid(pageId) || !Number.isInteger(idx) || idx < 1 || idx > 40) {
    throw new Error("Invalid OCR page or line number");
  }
  return `${pageId.toLowerCase()}_${pad2(idx)}`;
}

/** Local sync file name. The extension comes from the validated path. */
export function localOcrImageFile(
  idx: number,
  ext: OcrImageExtension,
): string {
  if (!Number.isInteger(idx) || idx < 1 || idx > 40) {
    throw new Error("Invalid OCR line number");
  }
  return `line_${pad2(idx)}.${ext}`;
}

/** Export image name. Unique because page id and line number are unique. */
export function exportOcrImageFile(
  pageId: string,
  idx: number,
  ext: OcrImageExtension,
): string {
  return `${stableOcrId(pageId, idx)}.${ext}`;
}

export function extensionForFormat(
  format: "webp" | "jpeg",
): OcrImageExtension {
  return format === "webp" ? "webp" : "jpg";
}
